var t=`0095-draniki`;var n=`world-0095`;var o=`BY`;var s=`eastern-europe`;var a=4;var r=31;var l={en:`Draniki`,ua:`Драники`};var u={en:`A classic dish from Belarus, featuring potato, yellow onion, chicken egg, sour cream. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Білорусь. Основні складники: картопля, жовта цибуля, куряче яйце, сметана. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:9,i:[[`potato`,760,`g`],[`yellow-onion`,130,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`chicken-egg`,1,`pcs`],[`all-purpose-flour`,50,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`sunflower-oil`,75,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`sour-cream`,135,`g`]]}];var d={slug:t,id:n,country:`BY`,region:s,servings:4,minutes:31,title:l,text:u,steps:g};export{o as country,d as default,n as id,r as minutes,s as region,a as servings,t as slug,g as steps,u as text,l as title};